function notionId(value) {
  if (
    typeof value !== "string" ||
    !/^([0-9a-f]{32}|[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12})$/i.test(value)
  )
    return "";
  return value
    .toLowerCase()
    .replaceAll("-", "")
    .replace(/^(.{8})(.{4})(.{4})(.{4})/, "$1-$2-$3-$4-");
}

function calendarWindow(at, dataSourceId) {
  const start = Date.parse(at);
  if (!Number.isFinite(start)) throw Error("The schedule did not provide a valid timestamp.");
  const source = notionId(dataSourceId);
  if (!source) throw Error("Set the Notion data source ID in the workflow settings.");
  return {
    dataSourceId: source,
    startDateTime: new Date(start).toISOString(),
    endDateTime: new Date(start + 365 * 86400000).toISOString(),
  };
}
export default ({ at, dataSourceId }) => calendarWindow(at, dataSourceId);

