function notionId(value) {
  if (
    typeof value !== "string" ||
    !/^([0-9a-f]{32}|[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12})$/i.test(value)
  )
    return "";
  return value
    .toLowerCase()
    .replaceAll("-", "")
    .replace(/^(.{8})(.{4})(.{4})(.{4})/, "$1-$2-$3-$4-");
}

function notionPageText(items) {
  if (
    !Array.isArray(items) ||
    items.some(
      (item) => item.type !== "text" || typeof (item.plain_text ?? item.text?.content) !== "string",
    )
  )
    return null;
  return items.map((item) => item.plain_text ?? item.text.content).join("");
}

function checkedNotionPage(page, event, dataSourceId, pageId = "") {
  const id = notionId(page?.id);
  if (
    page?.object !== "page" ||
    !id ||
    (pageId && id !== pageId) ||
    page.in_trash === true ||
    page.archived === true ||
    page.parent?.type !== "data_source_id" ||
    notionId(page.parent?.data_source_id) !== dataSourceId ||
    notionPageText(page.properties?.["Event ID"]?.rich_text) !== event.id
  ) {
    throw Error("Notion did not identify the exact event page in this data source.");
  }
  const props = page.properties;
  const current = props.Date?.date;
  const same =
    notionPageText(props.Name?.title) === event.title &&
    props.Link?.url === event.link &&
    Date.parse(current?.start) === Date.parse(event.start) &&
    Date.parse(current?.end) === Date.parse(event.end);
  return { id, same };
}
function matchedNotionEvent(list, event, source) {
  if (
    list?.object !== "list" ||
    !Array.isArray(list.results) ||
    list.has_more !== false ||
    list.next_cursor != null ||
    list.results.length > 1 ||
    list.request_status?.type === "incomplete" ||
    list.request_status?.type === "partial"
  ) {
    throw Error("Notion did not return one complete, unambiguous event search.");
  }
  return list.results.length ? checkedNotionPage(list.results[0], event, source) : null;
}

function eventProperties(event) {
  const text = (content) => ({ type: "text", text: { content } });
  return {
    "Event ID": { rich_text: [text(event.id)] },
    Name: { title: event.title ? [text(event.title)] : [] },
    Date: { date: { start: event.start, end: event.end, time_zone: null } },
    Link: { url: event.link },
  };
}

function notionEventFilter(event) {
  return { property: "Event ID", rich_text: { equals: event.id } };
}
function eventReservationKey(dataSourceId, eventId) {
  let hash = 0xcbf29ce484222325n;
  for (const byte of new TextEncoder().encode(dataSourceId + "\n" + eventId))
    hash = BigInt.asUintN(64, (hash ^ BigInt(byte)) * 0x100000001b3n);
  return "outlook-notion:" + hash.toString(16).padStart(16, "0");
}

export default async ({ event, dataSourceId }, ctx) => {
  const key = eventReservationKey(dataSourceId, event.id);
  const result = (status, pageId = "") => ({ receipt: { eventId: event.id, status, pageId } });
  const reserved = await ctx.state.insert(key, { eventId: event.id, dataSourceId });
  let matched;
  try {
    const search = await ctx.actions.call("notion.query_data_source", {
      dataSourceId,
      pageSize: 2,
      result_type: "page",
      filter: notionEventFilter(event),
    });
    matched = matchedNotionEvent(search, event, dataSourceId);
  } catch {
    if (reserved) await ctx.state.delete(key);
    return result("lookup_unconfirmed");
  }
  if (!reserved)
    return matched?.same ? result("unchanged", matched.id) : result("pending_review", matched?.id);
  if (matched?.same) {
    await ctx.state.delete(key);
    return result("unchanged", matched.id);
  }
  const properties = eventProperties(event);
  let saved;
  try {
    const reply = matched
      ? await ctx.actions.call("notion.update_page", {
          pageId: matched.id,
          properties: { Name: properties.Name, Date: properties.Date, Link: properties.Link },
        })
      : await ctx.actions.call("notion.create_page", {
          parent: { type: "data_source_id", data_source_id: dataSourceId },
          properties,
        });
    saved = checkedNotionPage(reply, event, dataSourceId, matched?.id);
    if (!saved.same) return result("pending_review", matched?.id);
  } catch {
    return result("pending_review", matched?.id);
  }
  await ctx.state.delete(key);
  return result(matched ? "updated" : "created", saved.id);
};

